import{_ as d,a0 as a,w as p,s as u,ao as r,I as e,x as t,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"來聊聊： Windows vs. Linux | LCTT x X-CMD","titleTemplate":false,"description":"來聊聊： Windows vs. Linux | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"來聊聊： Windows vs. Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"來聊聊： Windows vs. Linux | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170211 Lets Chat Windows vs. Linux","title":"來聊聊： Windows vs. Linux","tag":"201702","desc":""},"relativePath":"201702/20170211 Lets Chat Windows vs. Linux.md","filePath":"[post].md"}'),l={name:"201702/20170211 Lets Chat Windows vs. Linux.md"};function w(x,n,L,m,f,W){const s=a("Link");return p(),u("div",null,[n[13]||(n[13]=r('<h1 id="來聊聊-windows-vs-linux" tabindex="-1">來聊聊： Windows vs. Linux <a class="header-anchor" href="#來聊聊-windows-vs-linux" aria-label="Permalink to “來聊聊： Windows vs. Linux”">​</a></h1><blockquote><p>Windows 用户們，去還是留？</p></blockquote><p>Windows 依然是高居榜首的桌面操作系統，佔據 90% 以上的市場份額，遠超 macOS 和 Linux 。</p><p>從數據來看，儘管 linux 並不是 Windows 的頭號接班人，但近幾年越來越多用户轉向 Ubuntu、Linux Mint 等發行版，的確為 Linux 帶來了不小的增長。</p><p>面對 Windows 10 發佈以來招致的諸多批評，微軟後來採取的激進升級策略也明顯無濟於事。很多用户抱怨在不知情的情況下就被升級到了 Windows 10 ，這也促使部分用户決定放棄微軟產品而轉向 Linux 。</p><p>同時也有聲音指責微軟試圖通過 Windows 10 監視用户，同樣，這些批評助推更多用户投入 Linux 陣營。</p><h3 id="你怎麼選-windows-or-linux" tabindex="-1">你怎麼選： Windows or Linux？ <a class="header-anchor" href="#你怎麼選-windows-or-linux" aria-label="Permalink to “你怎麼選： Windows or Linux？”">​</a></h3><p>十幾年前，用户轉向 Linux 還主要是出於安全考慮，因為 Windows 才是全世界病毒和黑客的主要攻擊目標。</p><p>這有它的必然原因： Windows 是被最廣泛採用的操作系統，但那時微軟在安全上的設計並沒有今天這樣實用。</p><p>而近幾年，儘管 Linux 和 Windows 在安全方面的差距已沒有那麼明顯，但那些決定轉陣營的用户似乎又有了除安全以外的其它理由。</p><p>我們不想用什麼市場統計來説明問題，因為在這場 Windows 和 Linux 的持久戰中，這些數據顯得無關緊要。但是用户的聲音卻至關重要，因為它們總能代表並預示各個平台的走向。</p><p>這也是為什麼我們在這裏向讀者提出問題： Linux 是 Windows 合適的替代品麼？放棄 Windows 而選擇 Linux 是否明智？微軟是否該為用户流向 Linux 而感到緊張？請在評論中留下您的看法。</p><hr>',13)),e("p",null,[n[1]||(n[1]=t("via: ",-1)),i(s,{href:"http://news.softpedia.com/news/let-s-chat-windows-vs-linux-512842.shtml"},{default:o(()=>[...n[0]||(n[0]=[t("http://news.softpedia.com/news/let-s-chat-windows-vs-linux-512842.shtml",-1)])]),_:1})]),e("p",null,[n[5]||(n[5]=t("作者：",-1)),i(s,{href:"http://news.softpedia.com/editors/browse/bogdan-popa"},{default:o(()=>[...n[2]||(n[2]=[t("Bogdan Popa",-1)])]),_:1}),n[6]||(n[6]=t(" 譯者：",-1)),i(s,{href:"https://github.com/Dotcra"},{default:o(()=>[...n[3]||(n[3]=[t("Dotcra",-1)])]),_:1}),n[7]||(n[7]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[10]||(n[10]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:o(()=>[...n[9]||(n[9]=[t("Linux中國",-1)])]),_:1}),n[12]||(n[12]=t(" 榮譽推出",-1))])])}const h=d(l,[["render",w]]);export{v as __pageData,h as default};
